/**
 * Main class for the plugin.
 */
class WP_Messenger_Forward {

	/**
	 * Plugin options name.
	 */
	const OPTION_NAME = 'wp_messenger_forward_settings';

	/**
	 * Get default settings including messenger tokens and event toggles.
	 *
	 * @return array
	 */
	public static function get_default_settings() {
		return array(
			'telegram_bot_token'       => '',
			'telegram_chat_id'         => '',
			'bale_bot_token'           => '',
			'bale_chat_id'             => '',
			'rocketchat_url'           => 'https://chat.example.com/api',
			'rocketchat_user'          => '',
			'rocketchat_token'         => '',
			'events'                   => array(
				'forward_comment'       => true,
				'forward_post_publish'  => true,
				'forward_user_create'   => true,
				'forward_order_created' => false,
				'forward_order_status'  => false,
				'forward_product_view'  => false,
				'forward_page_view'     => false,
			),
		);
	}

	/**
	 * Get settings safely with defaults merged.
	 *
	 * @return array
	 */
	public static function get_settings() {
		$opts     = get_option( self::OPTION_NAME, array() );
		$defaults = self::get_default_settings();

		if ( ! is_array( $opts ) ) {
			return $defaults;
		}

		$merged = array_merge( $defaults, $opts );
		if ( ! isset( $opts['events'] ) || ! is_array( $opts['events'] ) ) {
			$merged['events'] = $defaults['events'];
		} else {
			$merged['events'] = array_merge( $defaults['events'], $opts['events'] );
		}

		return $merged;
	}

	/**
	 * Default settings including messenger tokens and event toggles on activation.
	 */
	public static function on_activate() {
		$opts = get_option( self::OPTION_NAME, false );
		if ( false === $opts || ! is_array( $opts ) ) {
			update_option( self::OPTION_NAME, self::get_default_settings() );
		} else {
			self::ensure_defaults();
		}
	}

	/**
	 * Register admin menu and hooks.
	 */
	public static function init() {
		register_activation_hook( __FILE__, array( __CLASS__, 'on_activate' ) );
		add_action( 'admin_menu', array( __CLASS__, 'add_admin_menu' ) );

		// Conditional hooks based on enabled events.
		$opts = self::get_settings();
		$ev   = $opts['events'];

		// Core WP events.
		if ( ! empty( $ev['forward_comment'] ) ) {
			add_action( 'comment_post', array( __CLASS__, 'forward_comment' ), 10, 1 );
		}
		if ( ! empty( $ev['forward_post_publish'] ) ) {
			add_action( 'publish_post', array( __CLASS__, 'forward_post_publish' ), 10, 1 );
		}
		if ( ! empty( $ev['forward_user_create'] ) ) {
			add_action( 'wp_insert_user', array( __CLASS__, 'forward_user_create' ), 10, 1 );
		}

		// WooCommerce events (only if WooCommerce is active and enabled).
		if ( function_exists( 'wc' ) ) {
			if ( ! empty( $ev['forward_order_created'] ) ) {
				add_action( 'woocommerce_order_created', array( __CLASS__, 'forward_order_created' ), 20, 1 );
			}
			if ( ! empty( $ev['forward_order_status'] ) ) {
				add_action( 'woocommerce_order_status_changed', array( __CLASS__, 'forward_order_status_changed' ), 20, 3 );
			}
			if ( ! empty( $ev['forward_product_view'] ) ) {
				add_action( 'woocommerce_product_viewed', array( __CLASS__, 'forward_product_viewed' ), 20, 1 );
			}
		}

		// Page view forwarding.
		if ( ! empty( $ev['forward_page_view'] ) ) {
			add_action( 'template_redirect', array( __CLASS__, 'forward_page_view' ) );
		}

		// Front-end support chat.
		add_shortcode( 'customer_chat', array( __CLASS__, 'customer_chat_shortcode' ) );
		add_action( 'wp_ajax_forward_message', array( __CLASS__, 'ajax_forward_message' ) );
		add_action( 'wp_ajax_nopriv_forward_message', array( __CLASS__, 'ajax_forward_message' ) );
		add_action( 'wp_ajax_send_reply', array( __CLASS__, 'ajax_send_reply' ) );
	}

	/**
	 * Ensure defaults on every load or when settings need checking.
	 */
	public static function ensure_defaults() {
		$opts     = get_option( self::OPTION_NAME, false );
		$defaults = self::get_default_settings();

		if ( false === $opts || ! is_array( $opts ) ) {
			update_option( self::OPTION_NAME, $defaults );
			return;
		}

		$updated = false;
		foreach ( $defaults as $k => $v ) {
			if ( ! array_key_exists( $k, $opts ) ) {
				$opts[ $k ] = $v;
				$updated    = true;
			}
		}

		// Merge events array safely.
		if ( ! isset( $opts['events'] ) || ! is_array( $opts['events'] ) ) {
			$opts['events'] = $defaults['events'];
			$updated        = true;
		} else {
			foreach ( $defaults['events'] as $ek => $ev ) {
				if ( ! array_key_exists( $ek, $opts['events'] ) ) {
					$opts['events'][ $ek ] = $ev;
					$updated               = true;
				}
			}
		}

		if ( $updated ) {
			update_option( self::OPTION_NAME, $opts );
		}
	}

	/**
	 * Add admin menu under Settings.
	 */
	public static function add_admin_menu() {
		add_options_page(
			'Messenger Forward Settings',
			'Messenger Forward',
			'manage_options',
			'wp-messenger-forward',
			array( __CLASS__, 'settings_page' )
		);
	}

