	/**
	 * Forward comment posted to all configured messengers.
	 */
	public static function forward_comment( $comment_id ) {
		$opts = self::get_settings();
		if ( empty( $opts['events']['forward_comment'] ) ) {
			return;
		}
		$comment = get_comment( $comment_id );
		if ( ! $comment ) {
			return;
		}
		$msg = sprintf(
			"🗒️ New comment on %s\n%s: %s (%s)\nIP: %s",
			get_the_title( $comment->comment_post_ID ),
			__( 'Commenter', 'wp-messenger-forward' ),
			esc_html( $comment->comment_author ),
			esc_html( $comment->comment_author_email ),
			esc_html( $comment->comment_author_IP )
		);
		self::send_to_messengers( $msg );
	}

	/**
	 * Forward post publish event.
	 */
	public static function forward_post_publish( $post_id ) {
		$opts = self::get_settings();
		if ( empty( $opts['events']['forward_post_publish'] ) ) {
			return;
		}
		$post = get_post( $post_id );
		if ( ! $post ) {
			return;
		}
		$msg = sprintf(
			"📢 New post published:\n%s\n%s\n%s",
			esc_html( $post->post_title ),
			get_permalink( $post_id ),
			__( 'Check it out!', 'wp-messenger-forward' )
		);
		self::send_to_messengers( $msg );
	}

	/**
	 * Forward new user creation.
	 */
	public static function forward_user_create( $user_id ) {
		$opts = self::get_settings();
		if ( empty( $opts['events']['forward_user_create'] ) ) {
			return;
		}
		$user = get_user_by( 'id', $user_id );
		if ( ! $user ) {
			return;
		}
		$msg = sprintf(
			"👤 New user registered:\nUsername: %s\nEmail: %s\nRole: %s",
			esc_html( $user->user_login ),
			esc_html( $user->user_email ),
			implode( ', ', (array) $user->roles )
		);
		self::send_to_messengers( $msg );
	}

	/**
	 * Forward WooCommerce order creation.
	 */
	public static function forward_order_created( $order_id ) {
		if ( ! function_exists( 'wc_get_order' ) ) {
			return;
		}
		$opts = self::get_settings();
		if ( empty( $opts['events']['forward_order_created'] ) ) {
			return;
		}
		$order = wc_get_order( $order_id );
		if ( ! $order ) {
			return;
		}
		$billing_name = trim( $order->get_billing_first_name() . ' ' . $order->get_billing_last_name() );
		$msg = sprintf(
			"🛒 New WooCommerce order #%d\nCustomer: %s (%s)\nTotal: %s\nStatus: %s\nLink: %s",
			$order->get_id(),
			esc_html( $order->get_billing_email() ),
			esc_html( $billing_name ),
			$order->get_total(),
			$order->get_status(),
			get_permalink( $order_id )
		);
		self::send_to_messengers( $msg );
	}

